edits.newText:
export function extensionArgs(
	options: Pick<OpenOptions, "loadExtension" | "keepExtensions" | "headless" | "selectorDir">,
): string[] {
	const effective = [options.loadExtension, options.selectorDir]
		.filter(Boolean)
		.join(",") || undefined;
	const args: string[] = [];
	if (effective) args.push(`--load-extension=${effective}`);
	if (options.keepExtensions) return args;
	if (options.loadExtension) args.push(`--disable-extensions-except=${effective}`);
	else if (options.headless)
		args.push(effective ? `--disable-extensions-except=${effective}` : "--disable-extensions");
	return args;
}

/** Dev Selector build under <root>/.output: the newer of chrome-mv3 / chrome-mv3-dev, if any. */
export function resolveDevSelectorDir(root: string): string | undefined {
	const candidates = ["chrome-mv3", "chrome-mv3-dev"].map((name) =>
		join(root, ".output", name),
	);
	let best: string | undefined;
	let bestTime = -Infinity;
	for (const dir of candidates) {
		let time: number;
		try {
			time = statSync(join(dir, "manifest.json")).mtimeMs;
		} catch {
			try {
				time = statSync(dir).mtimeMs;
			} catch {
				continue;
			}
		}
		if (time > bestTime) {
			bestTime = time;
			best = dir;
		}
	}
	return best;
}

